        {
            base.DeepCopyIn(
                (IFallout3MajorRecord)item,
                (IFallout3MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Book_FieldIndex.ObjectBounds) ?? true))
            {
                errorMask?.PushIndex((int)Book_FieldIndex.ObjectBounds);
